-- Two Christmas day trips (Le Barcarès 5 Dec, Andorra la Vella 6 Dec 2026).
-- Run once in the Supabase SQL editor. Safe to re-run: the tour row is updated and its
-- itinerary, FAQs and photos are replaced; the departure is only added if missing.
-- Photos: Wikimedia Commons, credited on each tour page; files live in the site at /photos/tours/.
begin;

-- Village de Noël de Le Barcarès: Navidad junto al mar
insert into public.tours (slug, title, subtitle, area, area_slug, duration_minutes, price_from_cents, summary, description, highlights, inclusions, exclusions, packing_list, meeting_point, seo_title, seo_description, status, published_at)
values ('village-de-noel-le-barcares', 'Village de Noël de Le Barcarès: Navidad junto al mar', 'Excursión de un día al gran pueblo navideño del Rosellón', 'Le Barcarès (Francia)', 'le-barcares', 720, 4000, 'Un sábado de diciembre para cruzar la frontera y pasar la tarde en uno de los pueblos navideños más grandes del sur de Francia, con la entrada y el autocar desde Barcelona incluidos.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Cada invierno, Le Barcarès, en la costa del Rosellón, se convierte en un enorme pueblo de Navidad a orillas del Mediterráneo. Calles de casetas iluminadas, decorados gigantes, pista de patinaje sobre hielo, atracciones y puestos de comida llenan el recinto durante toda la temporada."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Salimos de Barcelona por la mañana y llegamos a mediodía. A partir de ahí la tarde es tuya: pasea entre las luces, prueba los dulces y el vino caliente de los puestos, patina o sube a las atracciones. Al caer la noche, con todo encendido, volvemos en autocar a Barcelona."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Es un plan para ir en pareja, con amigos o en familia, sin preocuparte de conducir ni de aparcar."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La entrada al recinto del Village de Noël está incluida en el precio."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Vamos a Francia: lleva tu DNI o pasaporte en vigor."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Junto al mar refresca mucho por la tarde: ropa de abrigo y calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida, la bebida y las compras corren por tu cuenta."}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Créditos de las fotos"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Decoración navideña junto al paquebote Lydia, Le Barcarès: "}, {"type": "text", "text": "Anthony Levrot", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Le_Barcar%C3%A8s_-_66420_-_2024.01.17_D%C3%A9corations_de_No%C3%ABl_au_pied_du_%C2%AB_Lydia_%C2%BB_%C2%A9_Anthony_Levrot.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC BY-SA 4.0", "marks": [{"type": "link", "attrs": {"href": "https://creativecommons.org/licenses/by-sa/4.0"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "El paquebote Lydia en el paseo marítimo de Le Barcarès: "}, {"type": "text", "text": "Anthony Levrot", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:%22Lydia%22_(vue_avant_droite)_-_Le_Barcar%C3%A8s,_2018.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC BY-SA 4.0", "marks": [{"type": "link", "attrs": {"href": "https://creativecommons.org/licenses/by-sa/4.0"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Barcas catalanas en el puerto de Le Barcarès: "}, {"type": "text", "text": "Alan Mattingly", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Barques_catalanes_Le-Barcar%C3%A8s.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Puerto deportivo de Port-Barcarès con el Canigó nevado al fondo: "}, {"type": "text", "text": "Martine SODAIGUI", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:MRSBarca41.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC BY-SA 3.0", "marks": [{"type": "link", "attrs": {"href": "https://creativecommons.org/licenses/by-sa/3.0"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Mercado navideño de noche (foto ilustrativa, Lyon): "}, {"type": "text", "text": "Florian Pépellin", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:March%C3%A9_de_No%C3%ABl_de_Lyon_au_soir_du_8_d%C3%A9cembre_2017.JPG"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC BY-SA 4.0", "marks": [{"type": "link", "attrs": {"href": "https://creativecommons.org/licenses/by-sa/4.0"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Pista de hielo en un mercado navideño (foto ilustrativa, Estrasburgo): "}, {"type": "text", "text": "Pierre Rudloff", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Patinoire_march%C3%A9_de_No%C3%ABl_Strasbourg.JPG"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "Public domain", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/Commons:Public_domain"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}]}]}'::jsonb, '["Entrada al Village de Noël incluida", "Más de 6 horas libres en el recinto", "Casetas, luces y pista de hielo junto al mar", "Autocar privado ida y vuelta desde Barcelona"]'::jsonb, '["Autocar privado ida y vuelta desde Barcelona", "Entrada al Village de Noël", "Guía acompañante de Tripcelona durante el viaje", "Asistencia durante todo el viaje"]'::jsonb, '["Comida y bebida", "Compras y gastos personales"]'::jsonb, '["DNI o pasaporte en vigor", "Ropa de abrigo y calzado cómodo", "Tarjeta o efectivo para comida y compras"]'::jsonb, 'Estació del Nord, C/ d''Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Llegar 15 minutos antes.', 'Village de Noël de Le Barcarès: Navidad junto al mar', 'Un sábado de diciembre para cruzar la frontera y pasar la tarde en uno de los pueblos navideños más grandes del sur de Francia, con la entrada y el autocar', 'published', now())
on conflict (slug) do update set title = excluded.title, subtitle = excluded.subtitle, area = excluded.area, area_slug = excluded.area_slug, duration_minutes = excluded.duration_minutes, price_from_cents = excluded.price_from_cents, summary = excluded.summary, description = excluded.description, highlights = excluded.highlights, inclusions = excluded.inclusions, exclusions = excluded.exclusions, packing_list = excluded.packing_list, meeting_point = excluded.meeting_point, seo_title = excluded.seo_title, seo_description = excluded.seo_description, status = excluded.status;
insert into public.tour_departures (tour_id, starts_at, ends_at, capacity, price_cents, notes)
select id, ('2026-12-05 10:00'::timestamp at time zone 'Europe/Madrid'), ('2026-12-05 22:00'::timestamp at time zone 'Europe/Madrid'), 50, 4000, 'Plazas: 50 (autocar estándar). Ajustar en el admin si cambia.'
from public.tours where slug = 'village-de-noel-le-barcares'
on conflict (tour_id, starts_at) do nothing;
delete from public.tour_itinerary where tour_id = (select id from public.tours where slug = 'village-de-noel-le-barcares');
delete from public.tour_faqs where tour_id = (select id from public.tours where slug = 'village-de-noel-le-barcares');
delete from public.tour_images where tour_id = (select id from public.tours where slug = 'village-de-noel-le-barcares');
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 1, '10:00', 'Salida desde Barcelona', 'Nos vemos en el punto de encuentro 15 minutos antes. El autocar sale puntual.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 2, '12:30', 'Llegada a Le Barcarès', 'Entramos al Village de Noël con la entrada ya incluida.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 3, '12:30 – 19:30', 'Tarde libre en el pueblo navideño', 'Casetas, luces, pista de hielo, atracciones y puestos de comida. Tu guía te indica la hora y el punto de reencuentro.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 4, '19:30', 'Regreso a Barcelona', null from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 5, '22:00', 'Llegada a Barcelona', 'Hora aproximada, según el tráfico.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 1, '¿Necesito documentación?', 'Sí. Le Barcarès está en Francia, así que lleva tu DNI o pasaporte en vigor.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 2, '¿La entrada al recinto está incluida?', 'Sí, la entrada al Village de Noël está incluida en el precio de la excursión.' from public.tours where slug = 'village-de-noel-le-barcares';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 3, '¿A qué hora volvemos?', 'Salimos de Le Barcarès a las 19:30 y llegamos a Barcelona hacia las 22:00, según el tráfico.' from public.tours where slug = 'village-de-noel-le-barcares';
with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/01.jpg', 'Decoración navideña junto al paquebote Lydia, Le Barcarès', 1600, 1067, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/01.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
insert into public.tour_images (tour_id, media_id, storage_path, alt, sort_order) select t.id, m.id, 'tours/village-de-noel-le-barcares/01.jpg', 'Decoración navideña junto al paquebote Lydia, Le Barcarès', 1 from public.tours t, m where t.slug = 'village-de-noel-le-barcares';
with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/02.jpg', 'El paquebote Lydia en el paseo marítimo de Le Barcarès', 1600, 1200, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/02.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
insert into public.tour_images (tour_id, media_id, storage_path, alt, sort_order) select t.id, m.id, 'tours/village-de-noel-le-barcares/02.jpg', 'El paquebote Lydia en el paseo marítimo de Le Barcarès', 2 from public.tours t, m where t.slug = 'village-de-noel-le-barcares';
with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/03.jpg', 'Barcas catalanas en el puerto de Le Barcarès', 1600, 1118, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/03.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
insert into public.tour_images (tour_id, media_id, storage_path, alt, sort_order) select t.id, m.id, 'tours/village-de-noel-le-barcares/03.jpg', 'Barcas catalanas en el puerto de Le Barcarès', 3 from public.tours t, m where t.slug = 'village-de-noel-le-barcares';
with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/04.jpg', 'Puerto deportivo de Port-Barcarès con el Canigó nevado al fondo', 1600, 922, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/04.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
insert into public.tour_images (tour_id, media_id, storage_path, alt, sort_order) select t.id, m.id, 'tours/village-de-noel-le-barcares/04.jpg', 'Puerto deportivo de Port-Barcarès con el Canigó nevado al fondo', 4 from public.tours t, m where t.slug = 'village-de-noel-le-barcares';
with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/05.jpg', 'Mercado navideño de noche (foto ilustrativa, Lyon)', 1600, 1186, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/05.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
