with m as (insert into public.media (path, alt, width, height, mime, source_url) values ('tours/village-de-noel-le-barcares/06.jpg', 'Pista de hielo en un mercado navideño (foto ilustrativa, Estrasburgo)', 1600, 1200, 'image/jpeg', '/photos/tours/village-de-noel-le-barcares/06.jpg') on conflict (bucket, path) do update set alt = excluded.alt, source_url = excluded.source_url returning id)
