-- Andorra la Vella y su mercado de Navidad
insert into public.tours (slug, title, subtitle, area, area_slug, duration_minutes, price_from_cents, summary, description, highlights, inclusions, exclusions, packing_list, meeting_point, seo_title, seo_description, status, published_at)
values ('andorra-la-vella-mercado-de-navidad', 'Andorra la Vella y su mercado de Navidad', 'Excursión de un día a la capital del Pirineo vestida de Navidad', 'Andorra', 'andorra', 780, 3500, 'Un domingo de diciembre en Andorra la Vella: calles iluminadas, el mercado de Navidad y tiempo libre para pasear y hacer compras, con el autocar desde Barcelona incluido.', '{"type": "doc", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En diciembre, Andorra la Vella se llena de luces y adornos, y su mercado de Navidad ocupa el centro con casetas de artesanía, dulces y bebidas calientes. Todo ello rodeado de montañas, a unas tres horas y media de Barcelona."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "Al llegar, quien quiera puede unirse a un paseo guiado corto, de 20 a 30 minutos, para situarse en la ciudad. Después tienes la tarde libre: recorre el mercado, sube al casco antiguo hasta la Casa de la Vall y la iglesia de Sant Esteve, aprovecha las tiendas o date un baño en el balneario de Caldea (entrada aparte)."}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Bueno saber"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Andorra no está en la Unión Europea y hay control fronterizo: lleva tu DNI o pasaporte en vigor."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Al volver hay límites de compra en la aduana (tabaco, alcohol y otros productos)."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "En diciembre hace frío en el Pirineo: abrigo, guantes y calzado cómodo."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "La comida, las compras y entradas como la de Caldea corren por tu cuenta."}]}]}]}, {"type": "heading", "attrs": {"level": 3}, "content": [{"type": "text", "text": "Créditos de las fotos"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Árbol de Navidad iluminado en la plaça de la Rotonda, Andorra la Vella: "}, {"type": "text", "text": "FrankAndProust", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Pla%C3%A7a_de_la_Rotonda_Christmas_Tree_20231128_173438.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Avinguda Meritxell con luces de Navidad, Andorra la Vella: "}, {"type": "text", "text": "FrankAndProust", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Avinguda_Meritxell_Christmas_decorations_20231128_174025.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Casa de la Vall y Consell General, Andorra la Vella: "}, {"type": "text", "text": "FrankAndProust", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Casa_de_la_Vall_and_Consell_General_d%27Andorra_20231128_075456.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Iglesia de Sant Esteve en el casco antiguo de Andorra la Vella: "}, {"type": "text", "text": "FrankAndProust", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Sant_Esteve_Andorra_la_Vella_20231008_121913.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Balneario de Caldea junto al río Valira, Escaldes-Engordany: "}, {"type": "text", "text": "FrankAndProust", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Caldea_20231205_122111.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "Esquiadores bajo las cumbres nevadas del Pirineo andorrano: "}, {"type": "text", "text": "Jrodriguez9", "marks": [{"type": "link", "attrs": {"href": "https://commons.wikimedia.org/wiki/File:Andorra-snow-1940194.jpg"}}]}, {"type": "text", "text": ", "}, {"type": "text", "text": "CC0", "marks": [{"type": "link", "attrs": {"href": "http://creativecommons.org/publicdomain/zero/1.0/deed.en"}}]}, {"type": "text", "text": ", vía Wikimedia Commons."}]}]}]}]}'::jsonb, '["Mercado de Navidad de Andorra la Vella", "Paseo guiado opcional por el centro", "Tarde libre entre luces y tiendas", "Autocar privado ida y vuelta desde Barcelona"]'::jsonb, '["Autocar privado ida y vuelta desde Barcelona", "Guía acompañante de Tripcelona durante el viaje", "Paseo guiado opcional de 20-30 minutos", "Plano de la ciudad", "Asistencia durante todo el viaje"]'::jsonb, '["Comida y bebida", "Compras y gastos personales", "Entradas a Caldea u otras actividades"]'::jsonb, '["DNI o pasaporte en vigor (obligatorio)", "Ropa de abrigo, guantes y gorro", "Calzado cómodo"]'::jsonb, 'Estació del Nord, C/ d''Alí Bei 80, 08013 Barcelona (Metro L1 Arc de Triomf). Llegar 15 minutos antes.', 'Andorra la Vella y su mercado de Navidad', 'Un domingo de diciembre en Andorra la Vella: calles iluminadas, el mercado de Navidad y tiempo libre para pasear y hacer compras, con el autocar desde Barc', 'published', now())
