insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 1, '09:30', 'Salida desde Barcelona', 'Nos vemos en el punto de encuentro 15 minutos antes. El autocar sale puntual.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 2, '13:00', 'Llegada a Andorra la Vella', 'Paseo guiado opcional de 20 a 30 minutos por el centro.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 3, '13:30 – 19:00', 'Tarde libre y mercado de Navidad', 'Mercado navideño, casco antiguo, tiendas o Caldea. Tu guía te indica la hora y el punto de reencuentro.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 4, '19:00', 'Regreso a Barcelona', null from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_itinerary (tour_id, sort_order, time_label, title, body) select id, 5, '22:30', 'Llegada a Barcelona', 'Hora aproximada, según el tráfico y la frontera.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 1, '¿Necesito documentación?', 'Sí. Andorra no forma parte de la Unión Europea y hay control en la frontera: lleva tu DNI o pasaporte en vigor.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 2, '¿Puedo hacer compras en Andorra?', 'Sí, tendrás tiempo libre para comprar. Ten en cuenta los límites de la aduana al volver, sobre todo en tabaco y alcohol.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
insert into public.tour_faqs (tour_id, sort_order, question, answer) select id, 3, '¿A qué hora volvemos?', 'Salimos de Andorra a las 19:00 y llegamos a Barcelona hacia las 22:30, según el tráfico y la frontera.' from public.tours where slug = 'andorra-la-vella-mercado-de-navidad';
